public class JsonHelper {

    private static final ObjectMapper mapper = new ObjectMapper();

    public static String toJson(Object value, boolean prettyPrint) {
        if (value == null) return null;
        try {
            if (prettyPrint) {
                mapper.enable(SerializationFeature.INDENT_OUTPUT);
            } else {
                mapper.disable(SerializationFeature.INDENT_OUTPUT);
            }
            return mapper.writeValueAsString(value);
        } catch (Exception e) {
            e.printStackTrace();
            return null;
        }
    }
}

public class FilledTriangleUp implements IMarker {

    @Override
    public void draw(Graphics2D gfx, float centerX, float centerY, float size, Color fillColor) {
        // 获取三角形顶点
        float[][] points = MarkerTools.triangleUpPoints(centerX, centerY, size);
        Polygon polygon = new Polygon();
        for (float[] point : points) {
            polygon.addPoint(Math.round(point[0]), Math.round(point[1]));
        }
        gfx.setColor(fillColor);
        gfx.fillPolygon(polygon);
    }
}

