public final class StringBuilderExtensions {

    private StringBuilderExtensions() {

    }

    public static <T> StringBuilder appendJoin(StringBuilder builder, String separator, Collection<T> values) {
        if (builder == null || values == null) return builder;
        StringJoiner joiner = new StringJoiner(separator);
        for (T value : values) {
            joiner.add(value.toString());
        }
        builder.append(joiner.toString());
        return builder;
    }
}

